float pointLight(float fragX, float fragY, float lightX, float lightY, float screenH, float radius) { return 1; }

solution.solution.cpp:
#include <cmath>

struct Vec3 { float r, g, b; };

float mixf(float a, float b, float t) { return a + (b - a) * t; }
Vec3 mix3(Vec3 a, Vec3 b, float t) { return { mixf(a.r, b.r, t), mixf(a.g, b.g, t), mixf(a.b, b.b, t) }; }
float clampf(float x, float lo, float hi) { return x < lo ? lo : x > hi ? hi : x; }

float smoothstep(float e0, float e1, float x)
{
    const float t{ clampf((x - e0) / (e1 - e0), 0.0f, 1.0f) };
    return t * t * (3.0f - 2.0f * t);
}

Vec3 flash(Vec3 texel, float amount) { return mix3(texel, { 1, 1, 1 }, amount); }

bool dissolve(Vec3 texel, float noise, float threshold, Vec3& out)
{
    if (noise < threshold) return false;
    const float edge{ smoothstep(threshold, threshold + 0.05f, noise) };
    out = mix3({ 1.0f, 0.5f, 0.1f }, texel, edge);
    return true;
}

float pointLight(float fragX, float fragY, float lightX, float lightY, float screenH, float radius)
{
    const float ly{ screenH - lightY };
    const float d{ std::sqrt((fragX - lightX) * (fragX - lightX) + (fragY - ly) * (fragY - ly)) };
    return clampf(1.0f - d / radius, 0.15f, 1.0f);
}

unitTests:
bool nearC(Vec3 c, float r, float g, float b) { return std::fabs(c.r - r) < 1e-4f && std::fabs(c.g - g) < 1e-4f && std::fabs(c.b - b) < 1e-4f; }
TEST("built-ins") {
    CHECK_NEAR(mixf(2, 10, 0.25f), 4.0, 1e-6); CHECK_NEAR(clampf(5, 0, 1), 1.0, 1e-6);
    CHECK_NEAR(smoothstep(0, 1, 0.5f), 0.5, 1e-6); CHECK_NEAR(smoothstep(0, 1, 0.25f), 0.15625, 1e-6); CHECK_NEAR(smoothstep(0, 1, 2), 1.0, 1e-6);
    CHECK_NEAR(smoothstep(0.8f, 0.3f, 0.55f), 0.5, 1e-5); CHECK_NEAR(smoothstep(0.8f, 0.3f, 0.1f), 1.0, 1e-6);
}
TEST("flash") { CHECK(nearC(flash({ 0.2f, 0.4f, 0.6f }, 0.5f), 0.6f, 0.7f, 0.8f)); CHECK(nearC(flash({ 0.2f, 0.4f, 0.6f }, 0), 0.2f, 0.4f, 0.6f)); }
TEST("dissolve") {
    Vec3 out{ 0, 0, 0 }; const Vec3 tex{ 0, 0, 1 };
    CHECK(!dissolve(tex, 0.3f, 0.5f, out));
    CHECK(dissolve(tex, 0.6f, 0.5f, out)); CHECK(nearC(out, 0, 0, 1));
    CHECK(dissolve(tex, 0.525f, 0.5f, out)); CHECK(nearC(out, 0.5f, 0.25f, 0.55f));
}
TEST("light with flipped y") {
    CHECK_NEAR(pointLight(100, 500, 100, 100, 600, 200), 1.0, 1e-5);
    CHECK_NEAR(pointLight(100, 100, 100, 100, 600, 200), 0.15, 1e-5);
    CHECK_NEAR(pointLight(200, 500, 100, 100, 600, 200), 0.5, 1e-5);
}

